package com.neml.badminton.service;
import com.neml.badminton.dto.SportConfigurationDtos.*; import com.neml.badminton.entity.*; import com.neml.badminton.repository.*;
import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service
public class SportConfigurationService {
 private final ChampionshipRepository championships;private final BadmintonConfigurationRepository badminton;private final CricketConfigurationRepository cricket;private final MatchRepository matches;private final CricketMatchStateRepository cricketStates;private final RosterQuotaRuleRepository quotas;private final ConfigurationSectionService sections;private final CompetitionService competition;private final AuctionPolicyGuard policyGuard;private final AuctionConfigurationRepository auctionPolicies;private final TournamentSettingsRepository settings;
 public SportConfigurationService(ChampionshipRepository championships,BadmintonConfigurationRepository badminton,CricketConfigurationRepository cricket,MatchRepository matches,CricketMatchStateRepository cricketStates,RosterQuotaRuleRepository quotas,ConfigurationSectionService sections,CompetitionService competition,AuctionPolicyGuard policyGuard,AuctionConfigurationRepository auctionPolicies,TournamentSettingsRepository settings){this.championships=championships;this.badminton=badminton;this.cricket=cricket;this.matches=matches;this.cricketStates=cricketStates;this.quotas=quotas;this.sections=sections;this.competition=competition;this.policyGuard=policyGuard;this.auctionPolicies=auctionPolicies;this.settings=settings;}
 @Transactional public BadmintonConfigDto badminton(UUID cid){championship(cid,"BADMINTON");return dto(badminton.findFirstByChampionshipIdOrderByConfigurationVersionDesc(cid).orElseThrow(()->missing("Badminton configuration")));}
 @Transactional public BadmintonConfigDto updateBadminton(UUID cid,BadmintonConfigRequest r,User actor){Championship c=championship(cid,"BADMINTON");BadmintonConfiguration old=badminton.findLatestForUpdate(cid).orElseThrow(()->missing("Badminton configuration"));BadmintonConfigDto before=dto(old);
  if(!old.getConfigurationVersion().equals(r.expectedVersion()))conflict("Configuration version conflict: reload before saving");if(!matches.findAllByChampionshipIdOrderByMatchNumberAsc(cid).isEmpty())conflict("Badminton rules are locked after fixture generation");
  List<String> errors=new ArrayList<>();Set<String> codes=new HashSet<>();Set<Integer> orders=new HashSet<>();for(var x:r.rubbers()){try{FormatType.valueOf(x.rubberCode());}catch(Exception e){errors.add("Unsupported rubber code "+x.rubberCode());}if(!codes.add(x.rubberCode()))errors.add("Duplicate rubber code "+x.rubberCode());if(!orders.add(x.displayOrder()))errors.add("Duplicate rubber order "+x.displayOrder());if(x.bestOfGames()%2==0)errors.add(x.displayLabel()+" best-of-games must be odd");if(x.scoreCap()<x.pointsPerGame())errors.add(x.displayLabel()+" score cap must not be below points per game");}if(r.rubbers().stream().noneMatch(RubberRuleRequest::enabled))errors.add("At least one rubber must be enabled");if(!errors.isEmpty())bad(String.join("; ",errors));
  old.setStatus(ConfigurationStatus.SUPERSEDED);badminton.save(old);BadmintonConfiguration next=BadmintonConfiguration.builder().championship(c).configurationVersion(old.getConfigurationVersion()+1).status(ConfigurationStatus.VALID).presetCode(r.presetCode()).maximumAppearancesPerPlayer(r.maximumAppearancesPerPlayer()).multipleRubberCategoriesAllowed(r.multipleRubberCategoriesAllowed()).lineupChangesAfterStartAllowed(r.lineupChangesAfterStartAllowed()).tieHandling(r.tieHandling()).walkoverPolicy(r.walkoverPolicy()).retirementPolicy(r.retirementPolicy()).lineupVisibilityPolicy(r.lineupVisibilityPolicy()).build();
  r.rubbers().forEach(x->{boolean enabled=switch(r.presetCode()){case "BADMINTON_STANDARD_FIVE"->true;case "BADMINTON_COMPACT_THREE"->Set.of("MENS_SINGLES","WOMENS_SINGLES","MIXED_DOUBLES").contains(x.rubberCode());default->x.enabled();};next.getRubbers().add(BadmintonRubberRule.builder().configuration(next).rubberCode(x.rubberCode()).displayLabel(x.displayLabel()).shortLabel(x.shortLabel()).displayOrder(x.displayOrder()).participantCountPerSide(x.participantCountPerSide()).genderRule(x.genderRule()).bestOfGames(x.bestOfGames()).pointsPerGame(x.pointsPerGame()).winBy(x.winBy()).scoreCap(x.scoreCap()).enabled(enabled).build());});BadmintonConfigDto saved=dto(badminton.save(next));sections.markValid(cid,"SPORT_RULES",actor,List.of());competition.recordConfigurationAudit(cid,actor,"BADMINTON_RULES_CHANGED",saved.version(),Map.of("before",before,"after",saved));return saved;}
 @Transactional public CricketConfigDto cricket(UUID cid){championship(cid,"CRICKET");return dto(cricket.findFirstByChampionshipIdOrderByConfigurationVersionDesc(cid).orElseThrow(()->missing("Cricket configuration")));}
 @Transactional public CricketConfigDto updateCricket(UUID cid,CricketConfigRequest r,User actor){Championship c=championship(cid,"CRICKET");CricketConfiguration old=cricket.findLatestForUpdate(cid).orElseThrow(()->missing("Cricket configuration"));CricketConfigDto before=dto(old);if(!old.getConfigurationVersion().equals(r.expectedVersion()))conflict("Configuration version conflict: reload before saving");if(cricketStates.countByChampionshipId(cid)>0)conflict("Cricket scoring rules are locked after match scoring starts");
  int overs=switch(r.presetCode()){case "T10"->10;case "T20"->20;case "ODI"->50;default->r.oversPerInnings();};int bowler=switch(r.presetCode()){case "T10"->2;case "T20"->4;case "ODI"->10;default->r.maximumOversPerBowler();};
  List<String> errors=new ArrayList<>();if(bowler>overs)errors.add("Maximum overs per bowler cannot exceed innings overs");if(r.requiredWicketkeepers()>r.playersPerSide())errors.add("Required wicketkeepers cannot exceed the playing-side size");if("SUPER_OVER".equals(r.tiePolicy())&&r.maximumSuperOvers()<1)errors.add("Super-over policy requires at least one super over");if(!r.powerplayRanges().matches("\\d+-\\d+(,\\d+-\\d+)*"))errors.add("Powerplay ranges must use forms such as 1-6 or 1-6,16-20");if(!errors.isEmpty())bad(String.join("; ",errors));old.setStatus(ConfigurationStatus.SUPERSEDED);cricket.save(old);
  CricketConfigDto saved=dto(cricket.save(CricketConfiguration.builder().championship(c).configurationVersion(old.getConfigurationVersion()+1).status(ConfigurationStatus.VALID).presetCode(r.presetCode()).playersPerSide("CUSTOM".equals(r.presetCode())?r.playersPerSide():11).oversPerInnings(overs).maximumOversPerBowler(bowler).requiredWicketkeepers(r.requiredWicketkeepers()).tiePolicy(r.tiePolicy()).maximumSuperOvers(r.maximumSuperOvers()).powerplayRanges("CUSTOM".equals(r.presetCode())?r.powerplayRanges():"1-"+(overs==10?3:overs==20?6:10)).wideBallRuns(r.wideBallRuns()).noBallRuns(r.noBallRuns()).freeHitEnabled(r.freeHitEnabled()).tossRequired(r.tossRequired()).abandonmentPolicy(r.abandonmentPolicy()).administrativeTargetOverrideAllowed(r.administrativeTargetOverrideAllowed()).administrativeResultOverrideAllowed(r.administrativeResultOverrideAllowed()).playingXiLockPolicy(r.playingXiLockPolicy()).netRunRatePolicy(r.netRunRatePolicy()).build()));sections.markValid(cid,"SPORT_RULES",actor,List.of());competition.recordConfigurationAudit(cid,actor,"CRICKET_RULES_CHANGED",saved.version(),Map.of("before",before,"after",saved));return saved;}
 @Transactional public List<QuotaRuleDto> quotas(UUID cid){championship(cid,null);return quotas.findAllByChampionshipIdOrderByRuleCode(cid).stream().map(this::dto).toList();}
 @Transactional public List<QuotaRuleDto> replaceQuotas(UUID cid,List<QuotaRuleRequest> requests,int expectedVersion,User actor){Championship c=policyGuard.lockEditable(cid);AuctionConfiguration policy=auctionPolicies.findLatestForUpdate(cid).orElseThrow(()->missing("Auction configuration"));if(policy.getConfigurationVersion()!=expectedVersion)conflict("Configuration version conflict: reload before saving");if(!matches.findAllByChampionshipIdOrderByMatchNumberAsc(cid).isEmpty())conflict("Roster quotas are locked after fixture generation");List<RosterQuotaRule> current=quotas.findAllByChampionshipIdOrderByRuleCode(cid);List<QuotaRuleDto> before=current.stream().map(this::dto).toList();int version=quotas.findLatestConfigurationVersion(cid)+1;Set<String> codes=new HashSet<>();List<String> errors=new ArrayList<>();for(var r:requests){if(!codes.add(r.ruleCode()))errors.add("Duplicate quota rule code "+r.ruleCode());if(r.minimumCount()==null&&r.maximumCount()==null)errors.add(r.ruleCode()+" requires a minimum or maximum");if(r.minimumCount()!=null&&r.maximumCount()!=null&&r.minimumCount()>r.maximumCount())errors.add(r.ruleCode()+" minimum cannot exceed maximum");}if(!errors.isEmpty())bad(String.join("; ",errors));current.forEach(rule->rule.setStatus(ConfigurationStatus.SUPERSEDED));quotas.saveAll(current);int nextVersion=version;List<RosterQuotaRule> next=requests.stream().map(r->RosterQuotaRule.builder().championship(c).configurationVersion(nextVersion).status(ConfigurationStatus.VALID).sportCode(c.getSportType().toUpperCase(Locale.ROOT)).ruleCode(r.ruleCode()).categoryType(r.categoryType()).categoryValue(r.categoryValue()).minimumCount(r.minimumCount()).maximumCount(r.maximumCount()).appliesTo(r.appliesTo()).enabled(r.enabled()).validationMessage(r.validationMessage()).build()).collect(java.util.stream.Collectors.toCollection(ArrayList::new));if(next.isEmpty())next.add(RosterQuotaRule.builder().championship(c).configurationVersion(nextVersion).status(ConfigurationStatus.VALID).sportCode(c.getSportType().toUpperCase(Locale.ROOT)).ruleCode("__EMPTY__").categoryType("PLAYER_CATEGORY").categoryValue("NONE").minimumCount(0).maximumCount(0).appliesTo("SQUAD").enabled(false).validationMessage("Empty quota configuration marker").build());quotas.saveAll(next);TournamentSettings operational=settings.findByChampionshipId(cid).orElseThrow(()->missing("Tournament settings"));
  int female=next.stream().filter(q->q.getEnabled()&&"SQUAD".equals(q.getAppliesTo())&&"GENDER".equals(q.getCategoryType())&&"FEMALE".equals(q.getCategoryValue())).mapToInt(q->q.getMinimumCount()==null?0:q.getMinimumCount()).max().orElse(0);
  int male=next.stream().filter(q->q.getEnabled()&&"SQUAD".equals(q.getAppliesTo())&&"GENDER".equals(q.getCategoryType())&&"MALE".equals(q.getCategoryValue())).mapToInt(q->q.getMinimumCount()==null?0:q.getMinimumCount()).max().orElse(0);
  if(male+female>operational.getMaxSquadSize())bad("Gender minimums cannot exceed squad size");operational.setMinMale(male);operational.setMinFemale(female);settings.save(operational);policy.setConfigurationVersion(policy.getConfigurationVersion()+1);auctionPolicies.save(policy);sections.markValid(cid,"TEAMS_AND_ROSTERS",actor,List.of());List<QuotaRuleDto> saved=quotas(cid);competition.recordConfigurationAudit(cid,actor,"ROSTER_QUOTAS_CHANGED",version,Map.of("before",before,"after",saved));return saved;}
 private BadmintonConfigDto dto(BadmintonConfiguration c){return new BadmintonConfigDto(c.getConfigurationVersion(),c.getStatus(),c.getPresetCode(),c.getMaximumAppearancesPerPlayer(),c.getMultipleRubberCategoriesAllowed(),c.getLineupChangesAfterStartAllowed(),c.getTieHandling(),c.getWalkoverPolicy(),c.getRetirementPolicy(),c.getLineupVisibilityPolicy(),c.getRubbers().stream().map(r->new RubberRuleDto(r.getRubberCode(),r.getDisplayLabel(),r.getShortLabel(),r.getDisplayOrder(),r.getParticipantCountPerSide(),r.getGenderRule(),r.getBestOfGames(),r.getPointsPerGame(),r.getWinBy(),r.getScoreCap(),r.getEnabled())).toList());}
 private CricketConfigDto dto(CricketConfiguration c){return new CricketConfigDto(c.getConfigurationVersion(),c.getStatus(),c.getPresetCode(),c.getPlayersPerSide(),c.getOversPerInnings(),c.getMaximumOversPerBowler(),c.getRequiredWicketkeepers(),c.getTiePolicy(),c.getMaximumSuperOvers(),c.getPowerplayRanges(),c.getWideBallRuns(),c.getNoBallRuns(),c.getFreeHitEnabled(),c.getTossRequired(),c.getAbandonmentPolicy(),c.getAdministrativeTargetOverrideAllowed(),c.getAdministrativeResultOverrideAllowed(),c.getPlayingXiLockPolicy(),c.getNetRunRatePolicy());}
 private QuotaRuleDto dto(RosterQuotaRule r){return new QuotaRuleDto(r.getRuleCode(),r.getCategoryType(),r.getCategoryValue(),r.getMinimumCount(),r.getMaximumCount(),r.getAppliesTo(),r.getEnabled(),r.getValidationMessage());}
 private Championship championship(UUID cid,String sport){Championship c=championships.findById(cid).orElseThrow(()->missing("Championship"));if(sport!=null&&!sport.equalsIgnoreCase(c.getSportType()))bad("This championship is not configured for "+sport);return c;}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException missing(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m+" not found");}
}
